# pylint: skip-file
import difflib
import re
from collections.abc import Iterable, Mapping
from unittest.mock import patch

from deepdiff.helper import (
    booleans,
    bytes_type,
    get_type,
    np_ndarray,
    numbers,
    strings,
    times,
)
from ordered_set import OrderedSet

RFSW_DEFAULT_HELLO = b"""
  <hello xmlns="urn:ietf:params:xml:ns:netconf:base:1.0">
    <capabilities>
      <capability>urn:ietf:params:netconf:base:1.1</capability>
      <capability>urn:ietf:params:netconf:capability:writable-running:1.0</capability>
      <capability>urn:ietf:params:netconf:capability:xpath:1.0</capability>
      <capability>urn:ietf:params:netconf:capability:notification:1.0</capability>
      <capability>urn:ietf:params:netconf:capability:interleave:1.0</capability>
      <capability>urn:ietf:params:netconf:capability:with-defaults:1.0</capability>
    </capabilities>
  </hello>
"""


def _diff(self, level, parents_ids=frozenset(), _original_type=None, **_):  # noqa: C901
    """
    The main diff method

    **parameters**

    level: the tree level or tree node
    parents_ids: the ids of all the parent objects in the tree from the current node.
    _original_type: If the objects had an original type that was different than what currently exists in the level.t1
    and t2
    """
    if self._count_diff() is StopIteration:
        return

    if self._use_custom_operator(level):
        return

    if level.t1 is level.t2:
        return

    if self._skip_this(level):
        return

    if get_type(level.t1) != get_type(level.t2):
        report_type_change = True
        type_t2 = get_type(level.t2)
        if type_t2 in (str, type(None)):
            if str(level.t1).startswith("(") and str(level.t1).endswith(")"):
                report_type_change = False
                matched = re.match(re.compile(str(level.t1)[1:-1]), str(level.t2))
                if matched:
                    return
        for type_group in self.ignore_type_in_groups:
            if self.type_check_func(level.t1, type_group) and self.type_check_func(level.t2, type_group):
                report_type_change = False
                break
        if report_type_change:
            self._diff_types(level)
            return
        # This is an edge case where t1=None or t2=None and None is in the ignore type group.
        if level.t1 is None or level.t2 is None:
            self._report_result("values_changed", level)
            return

    if self.ignore_nan_inequality and isinstance(level.t1, float) and str(level.t1) == str(level.t2) == "nan":
        return

    if isinstance(level.t1, booleans):
        self._diff_booleans(level)

    if isinstance(level.t1, strings):
        self._diff_str(level)

    elif isinstance(level.t1, times):
        self._diff_datetimes(level)

    elif isinstance(level.t1, numbers):
        self._diff_numbers(level)

    elif isinstance(level.t1, Mapping):
        self._diff_dict(level, parents_ids)

    elif isinstance(level.t1, tuple):
        self._diff_tuple(level, parents_ids)

    elif isinstance(level.t1, (set, frozenset, OrderedSet)):
        self._diff_set(level)

    elif isinstance(level.t1, np_ndarray):
        self._diff_numpy_array(level, parents_ids)

    elif isinstance(level.t1, Iterable):
        self._diff_iterable(level, parents_ids, _original_type=_original_type)

    else:
        self._diff_obj(level, parents_ids)


def _diff_str(self, level):  # noqa: C901
    """Compare strings"""
    if self.ignore_string_case:
        level.t1 = level.t1.lower()
        level.t2 = level.t2.lower()

    if type(level.t1) == type(level.t2) and level.t1 == level.t2:  # NOQA
        return

    # do we add a diff for convenience?
    do_diff = True
    t1_str = level.t1
    t2_str = level.t2

    if isinstance(level.t1, bytes_type):
        try:
            t1_str = level.t1.decode("ascii")
        except UnicodeDecodeError:
            do_diff = False

    if isinstance(level.t2, bytes_type):
        try:
            t2_str = level.t2.decode("ascii")
        except UnicodeDecodeError:
            do_diff = False

    if t1_str == t2_str:
        return
    if t1_str != t2_str:
        if t1_str.startswith("(") and t1_str.endswith(")"):
            matched = re.match(re.compile(t1_str[1:-1]), t2_str)
            if matched:
                return
    if do_diff:
        if "\n" in t1_str or "\n" in t2_str:
            diff = difflib.unified_diff(t1_str.splitlines(), t2_str.splitlines(), lineterm="")
            diff = list(diff)
            if diff:
                level.additional["diff"] = "\n".join(diff)

    self._report_result("values_changed", level)


diff_fix = patch("deepdiff.DeepDiff._diff", _diff).start()
diff_str_fix = patch("deepdiff.DeepDiff._diff_str", _diff_str).start()
